document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("menu-toggle"),t=document.querySelector(".side-menu");if(!e||!t)return;window.addEventListener("keydown",t=>{if(t.ctrlKey||t.metaKey||t.altKey||t.shiftKey)return;if(t.key!=="Escape")return;if(document.querySelector("dialog.pf-modal[open]"))return;const n=document.querySelector("input.gallery-lightbox:checked");if(n){t.preventDefault(),t.stopPropagation(),n.checked=!1;return}t.preventDefault(),t.stopPropagation(),e.checked=!e.checked},!0),document.addEventListener("pointerdown",n=>e.checked&&!t.contains(n.target)&&!n.target.closest(".menu-toggle")&&(e.checked=!1))})